 Ext._define('rh.pvf.progression_h.Window', {
    extend: 'core.RestfulWindow',

    rest: 'rh.pvf.progression_h.Restful',

    width:850,
    //height:750,

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                items: [
                    this.getTabPanel(cfg)
                ]
            });

        return this._formPanel;
    },

    getTabPanel: function (cfg) {
        if (!this._tabPanel)
            this._tabPanel = Ext._create('Ext.TabPanel', {
                height: 600,
                border: false,
                activeTab: 0,
                deferredRender: false,
                items: [
                   this.getManagerPanel(cfg),
                   this.getTabHistory(cfg)
                ]
            })

        return this._tabPanel;
    },

    getManagerPanel: function (cfg) {
        var progression_id = cfg.action == 'create'?cfg.values.progression:cfg.data.progression;
        var config_id = cfg.action == 'create'?cfg.values.config:cfg.data.config;
        var employee_id = cfg.action == 'create'?cfg.values.employee_id:cfg.data.employee;
        var employee_schooling = cfg.action == 'create'?cfg.values.employee_schooling:cfg.data.employee_schooling;
        var possible_levels = cfg.action == 'create'?cfg.values.possible_levels:cfg.data.possible_levels;

        if (!this._managementPanel)
            this._managementPanel = Ext._create('Ext.Panel', {
                frame: true,
                border: false,
                //autoHeight: true,
                //monitorResize: true,
                height:600,
                scope: this,
                title: 'Principal',
                layout : 'form',
                items: [                   
                    {
                        xtype: "rest-autocompletefield",
                        name: "progression",
                        fieldLabel: "Classe Atual",
                        allowBlank: true,
                        rest: "rh.gfp.progression.horizontal_solicitation.Restful",
                        value: progression_id,
                        preFilter: [
                            {property: 'servidor', value: employee_id, stage: 100},
                        ],
                    },
                    {
                        xtype: "rest-autocompletefield",
                        name: "config",
                        fieldLabel: "Classe a Progredir",
                        allowBlank: true,
                        rest: "rh.gfp.progression.horizontal_config.Restful",
                        value: config_id,
                        gridConfig: {
                            configOrderToolBar: ['search', '>'],
                            columnAction: false,
                        },
                        preFilter: [
                            {property: 'schooling', value: employee_schooling, stage: 100},
                            {property: 'target_level__in', value: possible_levels, stage: 101},
                        ],
                    },
                    {
                        title: 'Adicionar Documento',
                        xtype: 'fieldset',
                        border: true,
                        items:[
                            this.getDocumentGrid(cfg)
                        ]
                      
                    },
                ]
            });

        return this._managementPanel;
    },

    _observeProgressionHDocumentGrid: function(cfg) {
        grid = this.getDocumentGrid();
        if(cfg.data && cfg.data.pk ) {
            grid.enable();
            grid.setParam('pr_progression_h', cfg.data.pk);
            grid.setFilterProperty('pr_progression_h__id', cfg.data.pk, 1001)
        }
        else {
            grid.setParam('pr_progression_h', 0);
            grid.setFilterProperty('pr_progression_h__id', 0, 1001, false);
            grid.getStore().removeAll();
            grid.disable();
        }        
    },
    
    getDocumentGrid: function(cfg) {
        if(!this._documentGrid) {
            this._documentGrid = Ext._create('rh.pvf.progression_h.document.Grid',{
                columnAction: false,
                region: 'center',
                height: 300,
                border: false,
                scope: this,
                columnAction: false,
            });
        }
        return this._documentGrid;
    },

    
    getTabHistory: function(cfg) {
        if(!this._tabAddress)
            this._tabAddress = Ext._create('Ext.Panel', {
                layout: 'form',
                title: 'Histórico',
                iconCls: '',
                border: false,
                frame: true,
                scope: this,
                autoHeight: true,
                items: [
                    this.getHistoryGrid(cfg)
                ]
            });
        return this._tabAddress;
    },

    getHistoryGrid: function(cfg) {
        if(!this._historyGrid) {
            this._historyGrid = Ext._create('rh.pvf.portalrequesthistory.Grid',{
                hideItemsToolbar: ['remove', 'download','add','edit'],
                columnAction: false,
                allowCreate: false,
                allowRemove: false,
                allowUpdate: false,
                region: 'center',
                height: 300,
                border: false,
                scope: this,
                columnAction: false,
            });
        }
        this._historyGrid.setFilterProperty('portal_request', cfg.action == 'create'? cfg.values.pk:cfg.data.pk)
        return this._historyGrid;
    },

    getButtons: function (cfg) {
        if (!this._buttons) {
            this._buttons = []
            this._buttons.push(
                new Ext._create('Ext.Button', {
                    text: 'Salvar',
                    height: 28,
                    scope: this,
                    hidden: cfg.action == "create"?false:true,
                    handler: function() { this.save(true); },
                }),
                new Ext._create('Ext.Button', {
                    text: 'Enviar ao Aprovador',
                    height: 28,
                    scope: this,
                    hidden: cfg.action == "update"?false:true,
                    handler: function () {
                        this.sendPRProgressionH(cfg);
                    },
                }),
                new Ext._create('Ext.Button', {
                    text: 'Fechar',
                    height: 28,
                    scope: this,
                    handler: function () {
                        this.close();
                    },
                })
            )
        } else {
            this.buttons.forEach(
                function(btn) { 
                    if (btn.text == 'Salvar') {
                        btn.hide()
                    } else if (btn.text == 'Enviar ao Aprovador') {
                        btn.show()
                    }
                }
            );
        }
        return this._buttons;
    },

    sendPRProgressionH: function(cfg){
        Ext.Msg.show({
            title:"Enviar Progressão Horizontal",
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            msg: 'Deseja enviar a solicitação ao aprovador ?',
            scope: this,

            fn: function (btn) {
                if (btn == 'no') return;
                var rest = Ext._create('rh.pvf.progression_h.Restful', {});
                var mask = new Ext.LoadMask(this.getEl(), {msg: 'Persistindo dados...'});
                params = {pk:cfg.action == 'create'?this.oId:cfg.data.pk }
                mask.show();
                rest.doRequest(
                    rest.getRoute('send', false, 'POST', {
                        scope: this,
                        params,
                        callback: function() {
                            mask.hide();
                            mask = undefined;
                        },
                        success: function(xhr) {
                            var rst = Ext.decode(xhr.responseText);
        
                            if(rst.success) {
                                if (this.ownerGrid)
                                    this.ownerGrid.getStore().reload()
                                else
                                    cfg.grid.getStore().reload()
        
                                this.destroy();
                            }
                            else
                                Ext.Msg.show({
                                    title: 'Atenção',
                                    icon: Ext.Msg.ERROR,
                                    buttons: Ext.Msg.OK,
                                    msg: rst.message
                                });
                        },
                        failure: function(xhr) {
                            Ext.Msg.show({
                                title: 'Atenção',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: 'Recurso indisponível no momento.'
                            });
                        },
                    })
                );
            }
        });
        
    },

    _observe: function(cfg) {
        if(this.oId) {
            grid = this.getDocumentGrid();
            grid.enable();
            grid.setParam('pr_progression_h', this.oId);
            grid.setFilterProperty('pr_progression_h__id', this.oId, 1001)
        }      
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});
        Ext.applyIf(cfg, {
            saveAndContinue: {
                scope: this,
                fn: function(instance) {
                    this.oId = instance.pk;
                    this.action = 'update';
                    this._observe(cfg);
                    this.getButtons(cfg);
                },
            },
        });
        rh.pvf.progression_h.Window.superclass.constructor.call(this, cfg);
        this._observeProgressionHDocumentGrid(cfg);
    },

});